func (s *Store) RegisterPatient(operator, name string) (*Patient, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if operator == "" || name == "" {
		return nil, fmt.Errorf("%w: 操作身份和患者姓名不能为空", ErrInvalid)
	}
	p := &Patient{
