	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

func (s *Store) sortedAuthorizations() []*Authorization {
	out := make([]*Authorization, 0, len(s.auths))
	for _, a := range s.auths {
		out = append(out, a)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

