	r, _ := s.SaveDraft("dr.lee", p.ID, v.ID, KindDiagnosis, "感冒")
	a, _ := s.CreateAuthorization("dr.lee", p.ID, "pharmacy", []string{v.ID}, []RecordKind{KindDiagnosis}, time.Now().Add(-time.Hour), time.Now().Add(time.Hour))
